/** The signed envelope of every delivery: `type` names the event, `data` is its subject. */
export interface AtlasWebhookEnvelope<T extends string, D> {
  /** The event id (also the `atlas-id` header). */
  id: string;
  type: T;
  /** When it was emitted (epoch ms). */
  timestamp: number;
  instance_id: string;
  /** Who caused the event; `system` when no request did. Absent on events recorded before it was added. */
  actor?: { type: "api_key" | "user" | "scim" | "sso" | "system"; id: string | null };
  /** The Idempotency-Key header of the request that caused the event, else null. */
  idempotency_key?: string | null;
  data: D;
}

/** Every canonical Atlas webhook event; narrow on `type`. */
export type AtlasWebhookEvent =
  | AtlasWebhookEnvelope<"access_policy.would_block", WebhookDataSecuritySignal>
  | AtlasWebhookEnvelope<"agent.access_decided", WebhookDataAgentAccess>
  | AtlasWebhookEnvelope<"agent.access_requested", WebhookDataAgentAccess>
